window.AUTH=window.AUTH||{};window.AUTH["12-484"]={"d":"12-484","id":"2012/12-484","n":"University of Texas Southwestern Medical Center v. Nassar","src":["osg"],"briefs":[{"k":"united-states","label":"Brief for the United States as amicus curiae supporting respondent","date":"","url":"https://www.justice.gov/osg/media/224711/dl?inline","side":"res","src":"osg","fmt":"PDF","detail":"https://www.justice.gov/osg/brief/university-tx-sw-med-ctr-v-nassar-amicus-merits","n":74}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep570/usrep570338/usrep570338.pdf","tr":true,"items":[{"t":"case","label":"Bibbs v. Block","cite":"778 F.2d 1318","y":1985,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/778/1318/","op":3,"by":{"0":"25"}},{"t":"case","label":"Borgo v. Goldin","cite":"204 F.3d 251","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/204/251/","by":{"0":"22"}},{"t":"case","label":"Burlington N. & Santa Fe Ry. Co. v. White","cite":"548 U.S. 53","y":2006,"id":"2005/05-259","sc":1,"op":3,"ar":3,"sum":"In a decision authored by Justice Stephen Breyer and joined by Chief Justice Roberts and six other justices, the Court held that in order to prevail on a claim of retaliatory discrimination, \"a plaintiff must show that a reasonable employee would have found the challenged action materially adverse, which in this context means it well might have dissuaded a reasonable worker from making or supporting a charge of discrimination.\" (internal citations omitted) Justice Samuel Alito wrote separately, agreeing with the result but arguing that the test adopted by the other members of the Court would eventually prove problematic.","sumSrc":"Oyez","by":{"0":"7, 27, 32"}},{"t":"case","label":"Carter v. Luminant Power Servs. Co.","cite":"2013 WL 1337365","y":2013,"court":"Apr. 3","op":1,"by":{"0":"23, 24"}},{"t":"case","label":"CBOCS W., Inc. v. Humphries","cite":"553 U.S. 442","y":2008,"id":"2007/06-1431","sc":1,"op":6,"ar":6,"sum":"Section 1981 encompasses retaliation claims. The 7-2 decision, written by Justice Stephen Breyer, relied heavily on the concept of stare decisis, or adherence to prior Court decisions, in reaching its conclusion.","sumSrc":"Oyez","by":{"0":"8, 14, 16, 20, 24, 26"}},{"t":"case","label":"Crawford v. Metropolitan Gov’t of Nashville & Davidson Cnty.","cite":"555 U.S. 271","y":2009,"id":"2008/06-1595","sc":1,"op":2,"ar":1,"sum":"The Court held that the anti-retaliation provision of Title VII extends to people who participate in an internal investigation, even if they are not speaking on their own initiative.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Cruz-Packer v. Chertoff","cite":"612 F. Supp. 2d 67","y":2009,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/612/67/","by":{"0":"18"}},{"t":"case","label":"Desert Palace, Inc. v. Costa","cite":"539 U.S. 90","y":2003,"id":"2002/02-679","sc":1,"sum":"The Court held that direct evidence is not required.","sumSrc":"Oyez","by":{"0":"23, 25, 29"}},{"t":"case","label":"EEOC v. General Lines, Inc.","cite":"865 F.2d 1555","y":1989,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/865/1555/","op":34,"ar":3,"by":{"0":"26"}},{"t":"case","label":"Federal Express Corp. v. Holowecki","cite":"552 U.S. 389","y":2008,"id":"2007/06-1322","sc":1,"op":2,"sum":"The Court, in a 7-2 opinion, upheld the Second Circuit, stating that the procedure used to file the document was consistent with the design and purpose of the ADEA.","sumSrc":"Oyez","by":{"0":"29, 30"}},{"t":"case","label":"Gomez-Perez v. Potter","cite":"553 U.S. 474","y":2008,"id":"2007/06-1321","sc":1,"op":6,"ar":11,"sum":"Noting the similarity between these statutes and the ADEA, Alito concluded that Congress had intended to include a retaliation prohibition in the ADEA. Chief Justice John G. Roberts and Justice Clarence Thomas filed dissenting opinions each joined in part by Justice Antonin Scalia.","sumSrc":"Oyez","by":{"0":"8, 13, 14, 16, 21"}},{"t":"case","label":"Gross v. FBL Fin. Servs., Inc.","cite":"557 U.S. 167","y":2009,"id":"2008/08-441","sc":1,"op":31,"ar":12,"sum":"The Court held that a plaintiff must show that age was the \"but-for\" cause for the defendant's action in an Age Discrimination in Employment Act claim.","sumSrc":"Oyez","by":{"0":"passim"}},{"t":"case","label":"Jackson v. Birmingham Bd. of Educ.","cite":"544 U.S. 167","y":2005,"id":"2004/02-1672","sc":1,"op":7,"ar":3,"sum":"The Court held that Title IX allowed suits alleging retaliation for reporting sex discrimination. Such retaliation, the majority reasoned, constituted intentional discrimination on the basis of sex in violation of Title IX. Jackson therefore had the right under Title IX to pursue his claim in court.","sumSrc":"Oyez","by":{"0":"8, 12, 13, 14, 15, 21"}},{"t":"case","label":"Johnson v. Legal Servs. of Ark., Inc.","cite":"813 F.2d 893","y":1987,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/813/893/","op":1,"by":{"0":"26"}},{"t":"case","label":"Kasten v. Saint-Gobain Performance Plastics Corp.","cite":"131 S. Ct. 1325","y":2011,"id":"2010/09-834","sc":1,"sum":"The Court held that the Fair Labor Standards Act applies to a complaint, whether oral or written.","sumSrc":"Oyez","by":{"0":"9, 30"}},{"t":"case","label":"Kubicko v. Ogden Logistics Servs.","cite":"181 F.3d 544","y":1999,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/181/544/","by":{"0":"23"}},{"t":"case","label":"Landgraf v. USI Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 20, 27"}},{"t":"case","label":"Lindh v. Murphy","cite":"521 U.S. 320","y":1997,"id":"1996/96-6298","sc":1,"sum":"The Court held that the 1996 version of the federal habeas statute, as to standards affecting the entitlement of state prisoners to federal habeas corpus relief, does not to apply to non-capital habeas corpus cases that were pending when the Act was enacted.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"McNutt v. Board of Trs. of the Univ. of Ill.","cite":"141 F.3d 706","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/141/706/","by":{"0":"23, 26"}},{"t":"case","label":"Mount Healthy City Sch. Dist. Bd. of Educ. v. Doyle","cite":"429 U.S. 274","y":1977,"id":"1976/75-1278","sc":1,"sum":"Writing for a unanimous Court, Justice Rehnquist held that the school district was not entitled to sovereign immunity, which generally extended to the states themselves and to state officials in their official capacities. He reasoned that the board was more akin to a municipal corporation, given its independent power to issue bonds and levy taxes.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"NLRB v. Transportation Mgmt. Corp.","cite":"462 U.S. 393","y":1983,"id":"1982/82-168","sc":1,"sum":"Acting on unfair labor practice charges filed by an employee of respondent, petitioner National Labor Relations Board found that respondent had discharged the employee, a busdriver, for his union activities, in violation of §§ 8(a)(1) and 8(a)(3) of the National Labor Relations Act. The Board applied its rule that the General Counsel has the burden of persuading the Board by a preponderance of the evidence that an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"op":1,"ar":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Porter v. Natsios","cite":"414 F.3d 13","y":2005,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/414/13/","by":{"0":"22"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs., Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"op":1,"sum":"The Court ruled 7-2 that the Ninth Circuit lacked jurisdiction to review the District Court's remand order. The Court relied on 28 U.S.C. 1447(d), which precludes appellate review of remands based on lack of subject-matter jurisdiction.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Price Waterhouse v. Hopkins","cite":"490 U.S. 228","y":1989,"id":"1988/87-1167","sc":1,"op":31,"ar":18,"sum":"The Supreme Court held that the court of appeals applied the right test, but should have placed the burden at “preponderance of the evidence” not “clear and convincing evidence”. On remand, Price Waterhouse would escape liability if it shows it would have denied Hopkins partnership even if she were not a woman.","sumSrc":"Oyez","by":{"0":"2, 9"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"0":"22, 30"}},{"t":"case","label":"Ross v. Communications Satellite Corp.","cite":"759 F.2d 355","y":1985,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/759/355/","by":{"0":"26"}},{"t":"case","label":"Smith v. Xerox Corp.","cite":"602 F.3d 320","y":2010,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/602/320/","op":2,"by":{"0":"6, 7"}},{"t":"case","label":"Sullivan v. Little Hunting Park, Inc.","cite":"396 U.S. 229","y":1969,"id":"1969/33","sc":1,"op":7,"ar":14,"sum":"Little Hunting Park is a Virginia nonstock corporation operating playground facilities and a community park for residents in an area in Fairfax County, Virginia. A membership share entitles a shareholder and his family to use its facilities, and under the bylaws when he rents his house he may assign the share to his tenant, subject to approval by the board of directors. The facilities have been open to any white …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"8, 12"}},{"t":"case","label":"Thompson v. North Am. Stainless, LP","cite":"131 S. Ct. 863","y":2011,"id":"2010/09-291","sc":1,"sum":"The Court held that an employer violates Title VII of the Civil Rights Acts by firing the fiancee of an employee who complains about workplace discrimination.","sumSrc":"Oyez","by":{"0":"7, 29, 30"}},{"t":"case","label":"Williams v. Boorstin","cite":"663 F.2d 109","y":1980,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/663/109/","op":1,"by":{"0":"26"}},{"t":"case","label":"Woodson v. Scott Paper Co.","cite":"109 F.3d 913","y":1997,"url":"https://www.courtlistener.com/c/F.3d/109/913/","op":3,"by":{"0":"23, 26"}},{"t":"case","label":"Zanders v. National R.R. Passenger Corp.","cite":"898 F.2d 1127","y":1990,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/898/1127/","by":{"0":"26"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","by":{"0":"4, 10, 13"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","subs":["(a)(1)"],"stext":{"head":"§623. Prohibition of age discrimination","paras":[[0,"(a) Employer practices"],[0,"It shall be unlawful for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual or otherwise discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's age;"],[1,"(2) to limit, segregate, or classify his employees in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's age; or"],[1,"(3) to reduce the wage rate of any employee in order to comply with this chapter."],[0,"(b) Employment agency practices"],[0,"It shall be unlawful for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of such individual's age, or to classify or refer for employment any individual on the basis of such individual's age."],[0,"(c) Labor organization practices"],[0,"It shall be unlawful for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his age;"],[1,"(2) to limit, segregate, or classify its membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's age;"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Opposition to unlawful practices; participation in investigations, proceedings, or litigation"],[0,"It shall be unlawful for an employer to discriminate against any of his employees or applicants for employment, for an employment agency to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because such individual, member or applicant for membership has opposed any practice made unlawful by this section, or because such individual, member or applicant for membership has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or litigation under this chapter."],[0,"(e) Printing or publication of notice or advertisement indicating preference, limitation, etc."],[0,"It shall be unlawful for an employer, labor organization, or employment agency to print or publish, or cause to be printed or published, any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, indicating any preference, limitation, specification, or discrimination, based on age."],[0,"(f) Lawful practices; age an occupational qualification; other reasonable factors; laws of foreign workplace; seniority system; employee benefit plans; discharge or discipline for good cause"],[0,"It shall not be unlawful for an employer, employment agency, or labor organization—"],[1,"(1) to take any action otherwise prohibited under subsections (a), (b), (c), or (e) of this section where age is a bona fide occupational qualification reasonably necessary to the normal operation of the particular business, or where the differentiation is based on reasonable factors other than age, or where such practices involve an employee in a workplace in a foreign country, and compliance with such subsections would cause such employer, or a corporation controlled by such employer, to violate the laws of the country in which such workplace is located;"],[1,"(2) to take any action otherwise prohibited under subsection (a), (b), (c), or (e) of this section—"],[2,"(A) to observe the terms of a bona fide seniority system that is not intended to evade the purposes of this chapter, except that no such seniority system shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title because of the age of such individual; or"],[2,"(B) to observe the terms of a bona fide employee benefit plan—"],[3,"(i) where, for each benefit or benefit package, the actual amount of payment made or cost incurred on behalf of an older worker is no less than that made or incurred on behalf of a younger worker, as permissible under section 1625.10, title 29, Code of Federal Regulations (as in effect on June 22, 1989); or"],[3,"(ii) that is a voluntary early retirement incentive plan consistent with the relevant purpose or purposes of this chapter."],[1,"Notwithstanding clause (i) or (ii) of subparagraph (B), no such employee benefit plan or voluntary early retirement incentive plan shall excuse the failure to hire any individual, and no such employee benefit plan shall require or permit the involuntary retirement of any individual specified by section 631(a) of this title, because of the age of such individual. An employer, employment agency, or labor organization acting under subparagraph (A), or under clause (i) or (ii) of subparagraph (B), shall have the burden of proving that such actions are lawful in any civil enforcement proceeding brought under this chapter; or"],[1,"(3) to discharge or otherwise discipline an individual for good cause."],[0,"(g) Repealed. Pub. L. 101–239, title VI, §6202(b)(3)(C)(i), Dec. 19, 1989, 103 Stat. 2233"],[0,"(h) Practices of foreign corporations controlled by American employers; foreign employers not controlled by American employers; factors determining control"],[0,"(1) If an employer controls a corporation whose place of incorporation is in a foreign country, any practice by such corporation prohibited under this section shall be presumed to be such practice by such employer."],[0,"(2) The prohibitions of this section shall not apply where the employer is a foreign person not controlled by an American employer."],[0,"(3) For the purpose of this subsection the determination of whether an employer controls a corporation shall be based upon the—"],[1,"(A) interrelation of operations,"],[1,"(B) common management,"],[1,"(C) centralized control of labor relations, and"],[1,"(D) common ownership or financial control,"],[0,"of the employer and the corporation."],[0,"(i) Employee pension benefit plans; cessation or reduction of benefit accrual or of allocation to employee account; distribution of benefits after attainment of normal retirement age; compliance; highly compensated employees"],[0,"(1) Except as otherwise provided in this subsection, it shall be unlawful for an employer, an employment agency, a labor organization, or any combination thereof to establish or maintain an employee pension benefit plan which requires or permits—"],[1,"(A) in the case of a defined benefit plan, the cessation of an employee's benefit accrual, or the reduction of the rate of an employee's benefit accrual, because of age, or"],[1,"(B) in the case of a defined contribution plan, the cessation of allocations to an employee's account, or the reduction of the rate at which amounts are allocated to an employee's account, because of age."],[0,"(2) Nothing in this section shall be construed to prohibit an employer, employment agency, or labor organization from observing any provision of an employee pension benefit plan to the extent that such provision imposes (without regard to age) a limitation on the amount of benefits that the plan provides or a limitation on the number of years of service or years of participation which are taken into account for purposes of determining benefit accrual under the plan."],[0,"(3) In the case of any employee who, as of the end of any plan year under a defined benefit plan, has attained normal retirement age under such plan—"],[1,"(A) if distribution of benefits under such plan with respect to such employee has commenced as of the end of such plan year, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of the actuarial equivalent of in-service distribution of benefits, and"],[1,"(B) if distribution of benefits under such plan with respect to such employee has not commenced as of the end of such year in accordance with section 1056(a)(3) of this title and section 401(a)(14)(C) of title 26, and the payment of benefits under such plan with respect to such employee is not suspended during such plan year pursuant to section 1053(a)(3)(B) of this title or section 411(a)(3)(B) of title 26, then any requirement of this subsection for continued accrual of benefits under such plan with respect to such employee during such plan year shall be treated as satisfied to the extent of any adjustment in the benefit payable under the plan during such plan year attributable to the delay in the distribution of benefits after the attainment of normal retirement age."],[0,"The provisions of this paragraph shall apply in accordance with regulations of the Secretary of the Treasury. Such regulations shall provide for the application of the preceding provisions of this paragraph to all employee pension benefit plans subject to this subsection and may provide for the application of such provisions, in the case of any such employee, with respect to any period of time within a plan year."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/623?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§623. Prohibition of age discrimination","tname":"Labor","by":{"0":"4"}},{"t":"usc","label":"29 U.S.C. § 633a","url":"https://www.law.cornell.edu/uscode/text/29/633a","subs":["(a)"],"stext":{"head":"§633a. Nondiscrimination on account of age in Federal Government employment","paras":[[0,"(a) Federal agencies affected"],[0,"All personnel actions affecting employees or applicants for employment who are at least 40 years of age (except personnel actions with regard to aliens employed outside the limits of the United States) in military departments as defined in section 102 of title 5, in executive agencies as defined in section 105 of title 5 (including employees and applicants for employment who are paid from nonappropriated funds), in the United States Postal Service and the Postal Regulatory Commission, in those units in the government of the District of Columbia having positions in the competitive service, and in those units of the judicial branch of the Federal Government having positions in the competitive service, in the Smithsonian Institution, and in the Government Publishing Office, the Government Accountability Office, and the Library of Congress shall be made free from any discrimination based on age."],[0,"(b) Enforcement by Equal Employment Opportunity Commission and by Librarian of Congress in the Library of Congress; remedies; rules, regulations, orders, and instructions of Commission: compliance by Federal agencies; powers and duties of Commission; notification of final action on complaint of discrimination; exemptions: bona fide occupational qualification"],[0,"Except as otherwise provided in this subsection, the Equal Employment Opportunity Commission is authorized to enforce the provisions of subsection (a) through appropriate remedies, including reinstatement or hiring of employees with or without backpay, as will effectuate the policies of this section. The Equal Employment Opportunity Commission shall issue such rules, regulations, orders, and instructions as it deems necessary and appropriate to carry out its responsibilities under this section. The Equal Employment Opportunity Commission shall—"],[1,"(1) be responsible for the review and evaluation of the operation of all agency programs designed to carry out the policy of this section, periodically obtaining and publishing (on at least a semiannual basis) progress reports from each department, agency, or unit referred to in subsection (a);"],[1,"(2) consult with and solicit the recommendations of interested individuals, groups, and organizations relating to nondiscrimination in employment on account of age; and"],[1,"(3) provide for the acceptance and processing of complaints of discrimination in Federal employment on account of age."],[0,"The head of each such department, agency, or unit shall comply with such rules, regulations, orders, and instructions of the Equal Employment Opportunity Commission which shall include a provision that an employee or applicant for employment shall be notified of any final action taken on any complaint of discrimination filed by him thereunder. Reasonable exemptions to the provisions of this section may be established by the Commission but only when the Commission has established a maximum age requirement on the basis of a determination that age is a bona fide occupational qualification necessary to the performance of the duties of the position. With respect to employment in the Library of Congress, authorities granted in this subsection to the Equal Employment Opportunity Commission shall be exercised by the Librarian of Congress."],[0,"(c) Civil actions; jurisdiction; relief"],[0,"Any person aggrieved may bring a civil action in any Federal district court of competent jurisdiction for such legal or equitable relief as will effectuate the purposes of this chapter."],[0,"(d) Notice to Commission; time of notice; Commission notification of prospective defendants; Commission elimination of unlawful practices"],[0,"When the individual has not filed a complaint concerning age discrimination with the Commission, no civil action may be commenced by any individual under this section until the individual has given the Commission not less than thirty days' notice of an intent to file such action. Such notice shall be filed within one hundred and eighty days after the alleged unlawful practice occurred. Upon receiving a notice of intent to sue, the Commission shall promptly notify all persons named therein as prospective defendants in the action and take any appropriate action to assure the elimination of any unlawful practice."],[0,"(e) Duty of Government agency or official"],[0,"Nothing contained in this section shall relieve any Government agency or official of the responsibility to assure nondiscrimination on account of age in employment as required under any provision of Federal law."],[0,"(f) Applicability of statutory provisions to personnel action of Federal departments, etc."],[0,"Any personnel action of any department, agency, or other entity referred to in subsection (a) of this section shall not be subject to, or affected by, any provision of this chapter, other than the provisions of sections 626(d)(3) and 631(b) of this title and the provisions of this section."],[0,"(g) Study and report to President and Congress by Equal Employment Opportunity Commission; scope"],[0,"(1) The Equal Employment Opportunity Commission shall undertake a study relating to the effects of the amendments made to this section by the Age Discrimination in Employment Act Amendments of 1978, and the effects of section 631(b) of this title."],[0,"(2) The Equal Employment Opportunity Commission shall transmit a report to the President and to the Congress containing the findings of the Commission resulting from the study of the Commission under paragraph (1) of this subsection. Such report shall be transmitted no later than January 1, 1980."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/633a?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§633a. Nondiscrimination on account of age in Federal Government employment","tname":"Labor","by":{"0":"13"}},{"t":"law","label":"Pub. L. No. 88-352","url":"https://www.govinfo.gov/link/statute/78/241","by":{"0":"20"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":136,"ar":4,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"0":"12"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(a)","(a)(1)","(a)(2)","(b)","(c)(1)","(c)(2)","(d)","(g)","(m)","(n)(1)","(n)(1)(A)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2000e–2. Unlawful employment practices","tname":"The Public Health and Welfare","by":{"0":"8, 18, 19, 2, 15, 15, 14, 15, 2, 15, 15, 15, 18, passim, 17, 17, 18, 3, 11"}},{"t":"usc","label":"42 U.S.C. § 2000e-3","url":"https://www.law.cornell.edu/uscode/text/42/2000e-3","subs":["(a)"],"stext":{"head":"§2000e–3. Other unlawful employment practices","paras":[[0,"(a) Discrimination for making charges, testifying, assisting, or participating in enforcement proceedings"],[0,"It shall be an unlawful employment practice for an employer to discriminate against any of his employees or applicants for employment, for an employment agency, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, to discriminate against any individual, or for a labor organization to discriminate against any member thereof or applicant for membership, because he has opposed any practice made an unlawful employment practice by this subchapter, or because he has made a charge, testified, assisted, or participated in any manner in an investigation, proceeding, or hearing under this subchapter."],[0,"(b) Printing or publication of notices or advertisements indicating prohibited preference, limitation, specification, or discrimination; occupational qualification exception"],[0,"It shall be an unlawful employment practice for an employer, labor organization, employment agency, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs, to print or publish or cause to be printed or published any notice or advertisement relating to employment by such an employer or membership in or any classification or referral for employment by such a labor organization, or relating to any classification or referral for employment by such an employment agency, or relating to admission to, or employment in, any program established to provide apprenticeship or other training by such a joint labor-management committee, indicating any preference, limitation, specification, or discrimination, based on race, color, religion, sex, or national origin, except that such a notice or advertisement may indicate a preference, limitation, specification, or discrimination based on religion, sex, or national origin when religion, sex, or national origin is a bona fide occupational qualification for employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-3?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§2000e–3. Other unlawful employment practices","tname":"The Public Health and Welfare","by":{"0":"17, 19, passim"}},{"t":"usc","label":"42 U.S.C. § 2000e-5","url":"https://www.law.cornell.edu/uscode/text/42/2000e-5","subs":["(a)","(b)","(g)","(g)(1)","(g)(2)(A)","(g)(2)(B)","(i)"],"by":{"0":"1, 22, 22, 22, 1, 21, 22, 20, 9, 11, 21, 22, 4"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","by":{"0":"1"}},{"t":"law","label":"Pub. L. No. 102-166","url":"https://www.govinfo.gov/link/statute/105/1071","by":{"0":"3"}},{"t":"usc","label":"20 U.S.C. § 1681","url":"https://www.law.cornell.edu/uscode/text/20/1681","stext":{"head":"§1681. Sex","paras":[[0,"(a) Prohibition against discrimination; exceptions"],[0,"No person in the United States shall, on the basis of sex, be excluded from participation in, be denied the benefits of, or be subjected to discrimination under any education program or activity receiving Federal financial assistance, except that:"],[0,"(1) Classes of educational institutions subject to prohibition"],[1,"in regard to admissions to educational institutions, this section shall apply only to institutions of vocational education, professional education, and graduate higher education, and to public institutions of undergraduate higher education;"],[0,"(2) Educational institutions commencing planned change in admissions"],[1,"in regard to admissions to educational institutions, this section shall not apply (A) for one year from June 23, 1972, nor for six years after June 23, 1972, in the case of an educational institution which has begun the process of changing from being an institution which admits only students of one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education or (B) for seven years from the date an educational institution begins the process of changing from being an institution which admits only students of only one sex to being an institution which admits students of both sexes, but only if it is carrying out a plan for such a change which is approved by the Secretary of Education, whichever is the later;"],[0,"(3) Educational institutions of religious organizations with contrary religious tenets"],[1,"this section shall not apply to an educational institution which is controlled by a religious organization if the application of this subsection would not be consistent with the religious tenets of such organization;"],[0,"(4) Educational institutions training individuals for military services or merchant marine"],[1,"this section shall not apply to an educational institution whose primary purpose is the training of individuals for the military services of the United States, or the merchant marine;"],[0,"(5) Public educational institutions with traditional and continuing admissions policy"],[1,"in regard to admissions this section shall not apply to any public institution of undergraduate higher education which is an institution that traditionally and continually from its establishment has had a policy of admitting only students of one sex;"],[0,"(6) Social fraternities or sororities; voluntary youth service organizations"],[1,"this section shall not apply to membership practices—"],[2,"(A) of a social fraternity or social sorority which is exempt from taxation under section 501(a) of title 26, the active membership of which consists primarily of students in attendance at an institution of higher education, or"],[2,"(B) of the Young Men's Christian Association, Young Women's Christian Association, Girl Scouts, Boy Scouts, Camp Fire Girls, and voluntary youth service organizations which are so exempt, the membership of which has traditionally been limited to persons of one sex and principally to persons of less than nineteen years of age;"],[0,"(7) Boy or Girl conferences"],[1,"this section shall not apply to—"],[2,"(A) any program or activity of the American Legion undertaken in connection with the organization or operation of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[2,"(B) any program or activity of any secondary school or educational institution specifically for—"],[3,"(i) the promotion of any Boys State conference, Boys Nation conference, Girls State conference, or Girls Nation conference; or"],[3,"(ii) the selection of students to attend any such conference;"],[0,"(8) Father-son or mother-daughter activities at educational institutions"],[1,"this section shall not preclude father-son or mother-daughter activities at an educational institution, but if such activities are provided for students of one sex, opportunities for reasonably comparable activities shall be provided for students of the other sex; and"],[0,"(9) Institution of higher education scholarship awards in \"beauty\" pageants"],[1,"this section shall not apply with respect to any scholarship or other financial assistance awarded by an institution of higher education to any individual because such individual has received such award in any pageant in which the attainment of such award is based upon a combination of factors related to the personal appearance, poise, and talent of such individual and in which participation is limited to individuals of one sex only, so long as such pageant is in compliance with other nondiscrimination provisions of Federal law."],[0,"(b) Preferential or disparate treatment because of imbalance in participation or receipt of Federal benefits; statistical evidence of imbalance"],[0,"Nothing contained in subsection (a) of this section shall be interpreted to require any educational institution to grant preferential or disparate treatment to the members of one sex on account of an imbalance which may exist with respect to the total number or percentage of persons of that sex participating in or receiving the benefits of any federally supported program or activity, in comparison with the total number or percentage of persons of that sex in any community, State, section, or other area: Provided, That this subsection shall not be construed to prevent the consideration in any hearing or proceeding under this chapter of statistical evidence tending to show that such an imbalance exists with respect to the participation in, or receipt of the benefits of, any such program or activity by the members of one sex."],[0,"(c) \"Educational institution\" defined"],[0,"For purposes of this chapter an educational institution means any public or private preschool, elementary, or secondary school, or any institution of vocational, professional, or higher education, except that in the case of an educational institution composed of more than one school, college, or department which are administratively separate units, such term means each such school, college, or department."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1681?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1681. Sex","tname":"Education","by":{"0":"12"}},{"t":"usc","label":"38 U.S.C. § 4311","url":"https://www.law.cornell.edu/uscode/text/38/4311","by":{"0":"22"}},{"t":"usc","label":"42 U.S.C. § 1981","url":"https://www.law.cornell.edu/uscode/text/42/1981","stext":{"head":"§1981. Equal rights under the law","paras":[[0,"(a) Statement of equal rights"],[0,"All persons within the jurisdiction of the United States shall have the same right in every State and Territory to make and enforce contracts, to sue, be parties, give evidence, and to the full and equal benefit of all laws and proceedings for the security of persons and property as is enjoyed by white citizens, and shall be subject to like punishment, pains, penalties, taxes, licenses, and exactions of every kind, and to no other."],[0,"(b) \"Make and enforce contracts\" defined"],[0,"For purposes of this section, the term \"make and enforce contracts\" includes the making, performance, modification, and termination of contracts, and the enjoyment of all benefits, privileges, terms, and conditions of the contractual relationship."],[0,"(c) Protection against impairment"],[0,"The rights protected by this section are protected against impairment by nongovernmental discrimination and impairment under color of State law."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1981?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1981. Equal rights under the law","tname":"The Public Health and Welfare","by":{"0":"16"}},{"t":"usc","label":"42 U.S.C. § 1981a","url":"https://www.law.cornell.edu/uscode/text/42/1981a","subs":["(b)(3)(D)"],"stext":{"head":"§1981a. Damages in cases of intentional discrimination in employment","paras":[[0,"(a) Right of recovery"],[0,"(1) Civil rights"],[1,"In an action brought by a complaining party under section 706 or 717 of the Civil Rights Act of 1964 [42 U.S.C. 2000e–5, 2000e–16] against a respondent who engaged in unlawful intentional discrimination (not an employment practice that is unlawful because of its disparate impact) prohibited under section 703, 704, or 717 of the Act [42 U.S.C. 2000e–2, 2000e–3, 2000e–16], and provided that the complaining party cannot recover under section 1981 of this title, the complaining party may recover compensatory and punitive damages as allowed in subsection (b), in addition to any relief authorized by section 706(g) of the Civil Rights Act of 1964, from the respondent."],[0,"(2) Disability"],[1,"In an action brought by a complaining party under the powers, remedies, and procedures set forth in section 706 or 717 of the Civil Rights Act of 1964 [42 U.S.C. 2000e–5, 2000e–16] (as provided in section 107(a) of the Americans with Disabilities Act of 1990 (42 U.S.C. 12117(a)), and section 794a(a)(1) of title 29, respectively) against a respondent who engaged in unlawful intentional discrimination (not an employment practice that is unlawful because of its disparate impact) under section 791 of title 29 and the regulations implementing section 791 of title 29, or who violated the requirements of section 791 of title 29 or the regulations implementing section 791 of title 29 concerning the provision of a reasonable accommodation, or section 102 of the Americans with Disabilities Act of 1990 (42 U.S.C. 12112), or committed a violation of section 102(b)(5) of the Act, against an individual, the complaining party may recover compensatory and punitive damages as allowed in subsection (b), in addition to any relief authorized by section 706(g) of the Civil Rights Act of 1964, from the respondent."],[0,"(3) Reasonable accommodation and good faith effort"],[1,"In cases where a discriminatory practice involves the provision of a reasonable accommodation pursuant to section 102(b)(5) of the Americans with Disabilities Act of 1990 [42 U.S.C. 12112(b)(5)] or regulations implementing section 791 of title 29, damages may not be awarded under this section where the covered entity demonstrates good faith efforts, in consultation with the person with the disability who has informed the covered entity that accommodation is needed, to identify and make a reasonable accommodation that would provide such individual with an equally effective opportunity and would not cause an undue hardship on the operation of the business."],[0,"(b) Compensatory and punitive damages"],[0,"(1) Determination of punitive damages"],[1,"A complaining party may recover punitive damages under this section against a respondent (other than a government, government agency or political subdivision) if the complaining party demonstrates that the respondent engaged in a discriminatory practice or discriminatory practices with malice or with reckless indifference to the federally protected rights of an aggrieved individual."],[0,"(2) Exclusions from compensatory damages"],[1,"Compensatory damages awarded under this section shall not include backpay, interest on backpay, or any other type of relief authorized under section 706(g) of the Civil Rights Act of 1964 [42 U.S.C. 2000e–5(g)]."],[0,"(3) Limitations"],[1,"The sum of the amount of compensatory damages awarded under this section for future pecuniary losses, emotional pain, suffering, inconvenience, mental anguish, loss of enjoyment of life, and other nonpecuniary losses, and the amount of punitive damages awarded under this section, shall not exceed, for each complaining party—"],[2,"(A) in the case of a respondent who has more than 14 and fewer than 101 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $50,000;"],[2,"(B) in the case of a respondent who has more than 100 and fewer than 201 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $100,000; and"],[2,"(C) in the case of a respondent who has more than 200 and fewer than 501 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $200,000; and"],[2,"(D) in the case of a respondent who has more than 500 employees in each of 20 or more calendar weeks in the current or preceding calendar year, $300,000."],[0,"(4) Construction"],[1,"Nothing in this section shall be construed to limit the scope of, or the relief available under, section 1981 of this title."],[0,"(c) Jury trial"],[0,"If a complaining party seeks compensatory or punitive damages under this section—"],[1,"(1) any party may demand a trial by jury; and"],[1,"(2) the court shall not inform the jury of the limitations described in subsection (b)(3)."],[0,"(d) Definitions"],[0,"As used in this section:"],[0,"(1) Complaining party"],[1,"The term \"complaining party\" means—"],[2,"(A) in the case of a person seeking to bring an action under subsection (a)(1), the Equal Employment Opportunity Commission, the Attorney General, or a person who may bring an action or proceeding under title VII of the Civil Rights Act of 1964 (42 U.S.C. 2000e et seq.); or"],[2,"(B) in the case of a person seeking to bring an action under subsection (a)(2), the Equal Employment Opportunity Commission, the Attorney General, a person who may bring an action or proceeding under section 794a(a)(1) of title 29, or a person who may bring an action or proceeding under title I of the Americans with Disabilities Act of 1990 [42 U.S.C. 12111 et seq.]."],[0,"(2) Discriminatory practice"],[1,"The term \"discriminatory practice\" means the discrimination described in paragraph (1), or the discrimination or the violation described in paragraph (2), of subsection (a)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1981a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1981a. Damages in cases of intentional discrimination in employment","tname":"The Public Health and Welfare","by":{"0":"8, 19, 6"}},{"t":"usc","label":"42 U.S.C. § 1982","url":"https://www.law.cornell.edu/uscode/text/42/1982","stext":{"head":"§1982. Property rights of citizens","paras":[[0,"All citizens of the United States shall have the same right, in every State and Territory, as is enjoyed by white citizens thereof to inherit, purchase, lease, sell, hold, and convey real and personal property."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1982?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1982. Property rights of citizens","tname":"The Public Health and Welfare","by":{"0":"12, 14"}}]};